#ifndef INCFLO_CRYO_SAMPLE_EXPERIMENT_H_
#define INCFLO_CRYO_SAMPLE_EXPERIMENT_H_

#include <AMReX_REAL.H>

namespace cryo_sample_exp
{

    // Prescribed grid kinematics for plunging samples (gold / sapphire /
    // diamond grids), measured on the linear motor. The spline data lives in
    // cryo_sample_experiment.cpp, which is generated by
    // experiments/make_sample_plunge_spline.py -- regenerate, do not edit.
    // Same sign convention as cryo_tc::ThermocoupleMotion: speed > 0 and
    // depth > 0 mean descending; depth is that of the grid's bottom edge
    // below the ethane surface, 0 at t = 0.
    struct SampleMotion
    {
        amrex::Real speed = amrex::Real(0.0);
        amrex::Real depth = amrex::Real(0.0);
    };

    SampleMotion evaluate_motion(amrex::Real time);

} // namespace cryo_sample_exp

#endif
